def kth_collatz_power_value(lo, hi, k):
 memo={1:0}
 def power(x):
  if x not in memo:memo[x]=1+power(3*x+1 if x%2 else x//2)
  return memo[x]
 return sorted(range(lo,hi+1),key=lambda x:(power(x),x))[k-1]

